INSERT INTO feature VALUES('exact-inference','theory','Exact inference by gluing, generic over the semiring',NULL,'partial','notable',NULL,'A factor graph holds exact tables over finite variables. `JunctionTree::new` builds a tree of cliques from an elimination order, and `with_tree` refuses a tree without the running intersection property by the variable that breaks it. Sum-product over any ordered semiring calibrates the tree: probability gives the marginals and max-times the most likely assignment, each held to enumeration. The clique beliefs glue on the separators, and a changed weight names the entry where two tables disagree. A cyclic family that agrees pair by pair is refused a joint by its supports. A weight past the integers is refused by name. The marginal problem is the next rung.','theory-probability','crates/theory-probability/tests/inference.rs','crate-tests','#6001');
